do $$ begin if current_database()<>'vacancy_marketing_test' or host(inet_server_addr())<>'127.0.0.1' or inet_server_port()<>55432 or shobj_description((select oid from pg_database where datname=current_database()),'pg_database') is distinct from 'vacancy-marketing-synthetic-only' then raise exception 'Wrong target';end if;end $$;
begin;alter table public.vacancies add column weekly_rent numeric(10,2),add column bond numeric(10,2);insert into public.properties values(md5('money-property')::uuid,md5('money-owner')::uuid);insert into public.rooms values(md5('money-room')::uuid,md5('money-property')::uuid);insert into public.vacancies(id,room_id,weekly_rent,bond) values(md5('money-v1')::uuid,md5('money-room')::uuid,12345.67,500);
-- The current amount/deposit columns are unconstrained numeric. Legacy mirror
-- columns must not reject high-denomination rents or deposits during RPC writes.
alter table public.vacancies alter column weekly_rent type numeric;
alter table public.vacancies alter column bond type numeric;

select public.qa_assert((select weekly_rent=12345.67 and bond=500 from public.vacancies where id=md5('money-v1')::uuid),'existing amounts preserved');update public.vacancies set weekly_rent=123456789012345678901234567890.12,bond=200000000.25 where id=md5('money-v1')::uuid;select public.qa_assert((select weekly_rent=123456789012345678901234567890.12 and bond=200000000.25 from public.vacancies where id=md5('money-v1')::uuid),'large amounts and decimals stored exactly');select public.qa_assert((select numeric_precision is null from information_schema.columns where table_schema='public' and table_name='vacancies' and column_name='weekly_rent'),'legacy precision cap removed');rollback;select public.qa_assert(not exists(select 1 from information_schema.columns where table_schema='public' and table_name='vacancies' and column_name='weekly_rent'),'synthetic transaction fully rolled back');